import{_ as o,o as a,c as t,ag as i}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"CoeHarMod Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Mods/CoeHarMod/index.md","filePath":"Community/Mods/CoeHarMod/index.md"}'),r={name:"Community/Mods/CoeHarMod/index.md"};function n(l,e,s,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="coeharmod-introduction" tabindex="-1">CoeHarMod Introduction <a class="header-anchor" href="#coeharmod-introduction" aria-label="Permalink to &quot;CoeHarMod Introduction&quot;">​</a></h1><h2 id="about-coeharmod" tabindex="-1">About CoeHarMod <a class="header-anchor" href="#about-coeharmod" aria-label="Permalink to &quot;About CoeHarMod&quot;">​</a></h2><p>CoeHarMod (和合共生, &quot;Harmony and Coexistence&quot;) is a large ruleset mod dedicated to optimizing and expanding the Unciv game experience.</p><h3 id="core-philosophy" tabindex="-1">Core philosophy <a class="header-anchor" href="#core-philosophy" aria-label="Permalink to &quot;Core philosophy&quot;">​</a></h3><blockquote><p>&quot;和合共生，万物各得其和以生，各得其养以成&quot; — Harmony and coexistence: all things live in their harmony and grow in their nourishment.</p></blockquote><p>The mod aims to provide a richer and more diverse game experience while maintaining game balance.</p><h3 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Mod resources</p><ul><li><a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">GitHub repository</a></li><li><a href="/Unciv/Community/Mods/CoeHarMod/changelog/">Changelog</a></li><li><a href="/Unciv/Community/Mods/CoeHarMod/changelog/roadmap.html">Roadmap</a></li></ul></div><h3 id="join-the-community" tabindex="-1">Join the community <a class="header-anchor" href="#join-the-community" aria-label="Permalink to &quot;Join the community&quot;">​</a></h3><p>For suggestions or issues, join our QQ group:</p><p><a href="https://qm.qq.com/q/amwSqibPmo" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/QQ%E7%BE%A4-%E7%82%B9%E5%87%BB%E5%8A%A0%E5%85%A5-green?logo=tencent-qq" alt="QQ group"></a></p><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><ol><li>Download the latest mod files</li><li>Put the mod folder into the game&#39;s <code>mods/</code> directory</li><li>Enable CoeHarMod in game settings</li><li>Start a new game to play</li></ol><div class="warning custom-block"><p class="custom-block-title">Note</p><ul><li>The mod only supports new games; it is incompatible with existing saves</li><li>Standard speed is recommended for the best experience</li><li>Some features require specific modes (e.g. Secret Societies)</li></ul></div><h3 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to &quot;Thanks&quot;">​</a></h3><p>Thanks to all players and developers who contributed to the mod!</p><p>Special thanks to:</p><ul><li>The Unciv development team for the excellent game platform</li><li>All players who tested and gave feedback</li><li>The Unciv Chinese community for their support</li></ul>',18)])])}const p=o(r,[["render",n]]);export{u as __pageData,p as default};
